//! tlx-native: the C ABI header (`tlx_abi.h`), the C compiler driver with an
//! on-disk cache (build.rs), and the dlopen loader (native.rs) for the compiled
//! tier (design.md §6.7). The C source itself is generated by the tlx-compile
//! crate (`tlx_compile::cgen`).

pub mod build;
pub mod mixed;
pub mod native;

use tlx_base::hash::mix64;

/// The ABI header shared by generated code and the host.
pub const ABI_HEADER: &str = include_str!("tlx_abi.h");
pub const ABI_VERSION: u32 = 5;

/// Fingerprint of a word-array state: the same mixing as the ABI header's
/// `tlx_fp_words` reference. The mixer is the shared `tlx_base::hash::mix64`;
/// the C header keeps its own copy only because it must not depend on Rust.
#[inline]
pub fn fp_words(s: &[u64]) -> u64 {
    const K: u64 = 0x9e3779b97f4a7c15;
    let step = |h: u64, w: u64, i: usize| mix64(h ^ w).wrapping_add(K.wrapping_mul(i as u64 + 1));
    let mut h = K ^ s.len() as u64;
    if s.len() <= 8 {
        for (i, w) in s.iter().enumerate() {
            h = step(h, *w, i);
        }
        return mix64(h);
    }
    // Longer states: 8 independent lanes (word i in lane i % 8), so the
    // mixing chains overlap.
    let mut l: [u64; 8] = std::array::from_fn(|j| h.wrapping_add(j as u64));
    let mut chunks = s.chunks_exact(8);
    let mut i = 0;
    for c in &mut chunks {
        for j in 0..8 {
            l[j] = step(l[j], c[j], i + j);
        }
        i += 8;
    }
    for (j, w) in chunks.remainder().iter().enumerate() {
        l[j] = step(l[j], *w, i + j);
    }
    for (j, x) in l.iter().enumerate() {
        h = step(h, *x, j);
    }
    mix64(h)
}

#[cfg(test)]
mod tests {
    /// Reference values of `tlx_fp_words` (tlx_abi.h) compiled with cc, for
    /// states of 0..=23 words `i * 0x1234567 + 7`: both sides must agree.
    #[test]
    fn fp_words_matches_c() {
        let s: Vec<u64> = (0..23u64).map(|i| i * 0x1234567 + 7).collect();
        let expected = include_str!("../tests/fp_c.txt");
        for line in expected.lines() {
            let (n, fp) = line.split_once(' ').unwrap();
            let n: usize = n.parse().unwrap();
            assert_eq!(super::fp_words(&s[..n]).to_string(), fp, "{n} words");
        }
    }
}
